import json,numpy as np
m=json.load(open('/app/runs/079/meta.json'))['cameras']['egocentric_mirrored_camera'];K=np.array(m['intrinsic_cv']);E=np.array(m['extrinsic_cv']);
def proj(p):
 c=E[:,:3]@p+E[:,3];u=K@c;return u[:2]/u[2]
p=np.array([.3979,-.1259,.17425])
for a in ([1,0,0],[0,1,0]):
 print(a,proj(p),proj(p+.03*np.array(a)),proj(p-.03*np.array(a)), 'delta',proj(p+.03*np.array(a))-proj(p-.03*np.array(a)))
PY

